const traverse = require('@babel/traverse').default;

const code = `
    const {a} = b;
    const {c: d} = b;
    ({ a } = b);
    c = { a };
    console.log(a);
`;

const ast = require("@babel/parser").parse(code);

traverse(ast, {
  Identifier(path) {
    if (path.node.name === "a") path.scope.rename('a', 'zzz');
  }
});

console.log('a shorthand =', ast.program.body[0].declarations[0].id.properties[0].shorthand);
console.log('c shorthand =', ast.program.body[1].declarations[0].id.properties[0].shorthand);
console.log('assign shorthand =', ast.program.body[2].expression.left.properties[0].shorthand);
console.log('literal shorthand =', ast.program.body[3].expression.right.properties[0].shorthand);

